"""Load R reference cases from tests/reference/*.json (generated by validation/r/*.R)."""

from __future__ import annotations

import json
from collections.abc import Mapping
from pathlib import Path
from typing import Any

REFERENCE_DIR = Path(__file__).parent / "reference"


def check_reference_meta(meta: Mapping[str, Any]) -> None:
    """Assert that the reference metadata records a successful R run."""
    case = meta.get("case", "<unknown>")
    assert meta.get("converged") is True, f"Reference {case!r}: the R run did not converge."


def load_reference(name: str) -> dict[str, Any]:
    """Return ``tests/reference/<name>.json`` after checking its metadata."""
    raw = dict(json.loads((REFERENCE_DIR / f"{name}.json").read_text(encoding="utf-8")))
    check_reference_meta(raw["meta"])
    return raw
